from pathlib import Path
import sys,json
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import pandas as pd
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.units import cm
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak,Image,KeepTogether
ROOT=Path(__file__).resolve().parents[1];R=ROOT/'pathsnap/results';V=ROOT/'pathsnap/visuals';OUT=ROOT/'pathsnap/report';OUT.mkdir(exist_ok=True,parents=True)
models=pd.read_csv(R/'model_comparison.csv');inv=pd.read_csv(R/'dataset_inventory.csv');net=pd.read_csv(R/'network_connectivity.csv');dec=pd.read_csv(R/'route_decoder_comparison.csv')
best=json.load(open(R/'bayesian_best.json'));tuned=json.load(open(R/'tuned_model_student_metrics.json'));dsummary=json.load(open(R/'route_decoder_summary.json'))
styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='Small',parent=styles['BodyText'],fontSize=8,leading=10));styles.add(ParagraphStyle(name='Sub',parent=styles['Heading2'],fontSize=13,spaceBefore=10));styles.add(ParagraphStyle(name='Title2',parent=styles['Title'],fontSize=24,leading=28,textColor=colors.HexColor('#17365D')))
story=[]
def P(s,style='BodyText'):story.append(Paragraph(str(s),styles[style]))
def table(data,widths=None):
 t=Table(data,colWidths=widths,repeatRows=1);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#17365D')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),7.5),('GRID',(0,0),(-1,-1),.35,colors.HexColor('#B7C9D6')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F1F5F9')]),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]));story.append(t);story.append(Spacer(1,10))
story += [Spacer(1,2*cm),P('PATHSNAP','Title2'),P('Distributed Map-Matching &amp; Route Reconstruction','Heading1'),P('Technical Report | PES University UE24CS352A Machine Learning Hackathon','Heading2'),Spacer(1,1*cm),P('Prepared from the supplied 80 training trips and 10 student-testing trips. All numerical results below are generated by the included scripts and saved experiment artifacts.'),Spacer(1,2*cm),P('<b>Important partition note:</b> The supplied archive contains 80 training trips and 10 student-testing trips. It does not include the separate 10-trip evaluator-testing partition described in the hackathon instructions. Evaluator data must be added by the organisers for final evaluation; it was not fabricated or substituted.'),PageBreak()]
P('1. Problem and system overview','Heading1');P('PathSnap reconstructs plausible road-segment sequences from noisy GPS observations. The implementation has four stages: parse trip files, generate nearby directed-road candidates and features, score candidates with a trained classifier, and apply a Viterbi decoder that favours connected directed arcs. A FastAPI service runs the inference pipeline; a separate browser UI requests a trip and displays the predicted road geometry and aggregate evaluation metrics.')
P('2. Dataset understanding and exploratory analysis','Heading1')
tr=inv.groupby('partition').agg(trips=('trip_id','count'),gps_mean=('gps_points','mean'),gps_min=('gps_points','min'),gps_max=('gps_points','max'),nodes_mean=('nodes','mean'),arcs_mean=('arcs','mean'),route_arcs_mean=('route_arcs','mean'),missing_gps=('missing_gps','sum')).reset_index()
table([['Partition','Trips','Mean GPS pts','GPS range','Mean nodes','Mean arcs','Mean route arcs','Missing GPS']]+[[r.partition,int(r.trips),round(r.gps_mean,1),f'{int(r.gps_min)}–{int(r.gps_max)}',round(r.nodes_mean),round(r.arcs_mean),round(r.route_arcs_mean,1),int(r.missing_gps)] for r in tr.itertuples()])
P('The raw archive contains 80 training trips and 10 student-testing trips. Each trip contains a .track file (longitude, latitude, timestamp), .nodes (longitude, latitude), .arcs (directed from-node and to-node row indices), and .route (ordered arc-row IDs). The EDA script checks file availability, row counts, missing values, timestamp ordering, gaps, invalid arc references and undirected network components. No missing GPS coordinate/timestamp rows were found in the supplied trips. The mean GPS point counts were approximately 2,605 in training and 1,916 in student testing. The dataset contains irregular time gaps, including occasional very large gaps; these should be treated as trajectory discontinuities rather than assumed one-second movement.')
netmeans=net.groupby('partition')[['connected_components','isolated_nodes','largest_component_nodes']].mean().round(1)
table([['Partition','Mean components','Mean isolated nodes','Mean largest component']]+[[idx,*[str(v) for v in row.values]] for idx,row in netmeans.iterrows()])
P('The network analysis reports multiple connected components per trip on average, but no isolated nodes in the examined trips. This is expected in a trip-local road-network extract that can include nearby disconnected road fragments. Distances are calculated in a local metric approximation derived from longitude/latitude rather than raw degree-space Euclidean distance.')
P('A Folium EDA map is supplied at <b>pathsnap/visuals/trip_00000000_eda.html</b>. It overlays the raw GPS trace and supplied reference route for an offline development visualisation. The reference route is not sent to the browser UI during prediction.')
P('3. Candidate generation and feature engineering','Heading1');P('For each GPS point, a KD-tree retrieves the eight nearest directed-arc midpoints. Candidate features are: GPS-to-midpoint distance (m), absolute heading difference (degrees), road-segment length (m), road bearing, estimated GPS speed (m/s), timestamp gap (s), heading-change placeholder, and candidate rank. The target candidate is the geometrically nearest directed arc among the supplied reference-route arcs. This route-constrained nearest-segment label is used only in offline training and internal development evaluation. It is not passed as an input feature to the classifier.')
P('The training scripts sample 120 evenly spaced GPS observations per trip for the five-model comparison. Bayesian optimisation uses a smaller 40-observation-per-trip sample for a compact search. The search/final tuned model is trained only from the 80 training trips. This sampling is recorded in model metadata. The student-testing results are development-stage measurements and must not be interpreted as evaluator-test results.')
P('4. Model experimentation and comparison','Heading1');P('Five distinct classifiers were trained and compared using three-fold GroupKFold cross-validation, with trip ID as the group so observations from one trip are not split across folds. The student-testing partition was used for development comparison. Candidate-level macro-F1 and log loss are reported alongside observation-level Top-1 Accuracy (choose the highest positive-class candidate score within each group of eight candidates and test whether it is the reference-route candidate).')
header=['Model','CV Macro F1','Student Top-1','Student Macro F1','Log Loss','Train s','Infer s']
rows=[header]
for r in models.itertuples():rows.append([r.model,f'{r.cv_macro_f1:.3f}',f'{r.student_top1_accuracy:.3f}',f'{r.student_macro_f1:.3f}',f'{r.student_log_loss:.3f}',f'{r.training_seconds:.2f}',f'{r.inference_seconds:.3f}'])
table(rows,[4.0*cm,2.0*cm,2.0*cm,2.0*cm,1.7*cm,1.5*cm,1.5*cm])
for name,why,strength,limit in [
('Logistic Regression','A simple probabilistic linear baseline for candidate features.','Fast and interpretable; supplies probabilities for the decoder.','Linear boundaries may not capture nonlinear spatial/heading interactions.'),
('K-Nearest Neighbours','A local similarity baseline for candidate feature vectors.','Can model irregular local decision regions without a complex fit.','Inference is slower and sensitive to feature scaling and class imbalance.'),
('Decision Tree','A transparent nonlinear baseline.','Captures feature interactions and is easy to explain.','Single-tree variance and overfitting risk; probability estimates can be coarse.'),
('Random Forest','An ensemble of decorrelated trees for nonlinear candidate scoring.','Best initial group-CV macro-F1 among the five tested models; probability output works with HMM emissions.','Larger model and weaker interpretability; depends on the quality of candidate generation and labels.'),
('Extra Trees','A randomized tree ensemble to test whether additional split randomisation helps.','Captures nonlinear relationships and trains efficiently.','Randomisation may reduce fit to the specific candidate patterns; less strong than Random Forest here.')]:
 r=models[models.model==name].iloc[0];P(name,'Sub');P(f'<b>Suitability:</b> {why} <b>Strengths:</b> {strength} <b>Limitations:</b> {limit} <b>Configuration:</b> {r.config[:450]}... <b>Student-test candidate Macro F1:</b> {r.student_macro_f1:.3f}; <b>observation Top-1:</b> {r.student_top1_accuracy:.3f}; <b>Log Loss:</b> {r.student_log_loss:.3f}.')
P('Model selection: Random Forest was selected because it achieved the strongest group-aware CV macro-F1 (0.865) and strongest student-test candidate macro-F1 (0.870) among the initial five models, while also providing probability scores for sequential decoding. The student Top-1 score was 0.785. The comparison does not establish a universal winner; it is specific to the sampled observations and route-constrained labels used here.')
for fn,cap in [('cv_macro_f1.png','Figure 1. Group-aware cross-validation macro-F1.'),('student_accuracy.png','Figure 2. Student-testing observation-level Top-1 Accuracy.'),('student_macro_f1.png','Figure 3. Student-testing candidate-level Macro F1.'),('student_log_loss.png','Figure 4. Student-testing candidate-level Log Loss.')]:
 story.append(Image(str(V/fn),width=15.5*cm,height=8.0*cm));P(cap,'Small')
P('5. Bayesian hyperparameter optimisation','Heading1');P(f"Optuna's Tree-structured Parzen Estimator (TPE) sampler was used as a Bayesian search strategy. The objective was two-fold trip-grouped cross-validation macro-F1 on the 80 training trips. Three trials were retained. The best parameters were {best['best_params']}, with search CV macro-F1 {best['best_cv_macro_f1']:.3f}. Search sample size: {best['search_training_samples']:,} candidate rows. The compact search was deliberately limited to three trials to keep runtime practical; more trials could be run on available hardware.")
trials=pd.read_csv(R/'bayesian_trials.csv');table([['Trial','CV Macro F1','Parameters']]+[[int(x.trial),f'{x.value:.3f}',x.params[:100]] for x in trials.itertuples()])
P(f"The tuned model's student-testing candidate Macro F1 was {tuned['candidate_level_macro_f1']:.3f}, candidate-level log loss {tuned['candidate_level_log_loss']:.3f}, and observation-level Top-1 Accuracy {tuned['observation_top1_accuracy']:.3f}. The search and final model artifacts are saved in pathsnap/results and pathsnap/models. The final tuned model is fit using the 40-observation-per-trip search sample; this is explicitly recorded and can be refit on a larger sample if compute time permits.")
P('6. HMM and Viterbi route reconstruction','Heading1');P('The hidden state at each GPS observation is one of the eight candidate directed road arcs. Emission scores are the classifier positive-class probabilities, normalised across the candidates for that observation, with a distance penalty. The transition model rewards a pair when the previous directed arc destination node equals the next directed arc source node; otherwise it applies a fixed penalty. Viterbi stores the best predecessor state and backtracks to produce the highest-scoring sequence. Candidate-to-arc IDs are retained throughout. Invalid arc IDs are skipped and disconnected transitions are penalised.')
table([['Metric (mean over 10 student trips)','Classifier only','Classifier + HMM'],['Pointwise route accuracy',f"{dsummary['candidate_top1_accuracy']:.3f}",f"{dsummary['hmm_accuracy']:.3f}"],['Directed route continuity',f"{dsummary['classifier_route_continuity']:.3f}",f"{dsummary['hmm_route_continuity']:.3f}"]])
P(f"The HMM increased measured directed route continuity from {dsummary['classifier_route_continuity']:.3f} to {dsummary['hmm_route_continuity']:.3f}, while pointwise route accuracy decreased from {dsummary['candidate_top1_accuracy']:.3f} to {dsummary['hmm_accuracy']:.3f}. This is an observed trade-off: the current transition penalty prioritises connected sequences and can override locally accurate candidate choices. Decoder parameters should be tuned using training and student-testing data only.")
P('7. API, UI and deployment','Heading1');P('The FastAPI backend runs on Laptop 1 and loads pathsnap/models/final_model.joblib. It exposes GET /health, GET /trips and POST /predict/{trip_id}. Each inference request is logged. The UI on Laptop 2 is a static HTML page using Leaflet; it loads trip IDs from the API, submits the selected ID, and displays the predicted road segments, GPS trace, observation count, internal accuracy and route continuity. The API holds reference routes server-side and returns only aggregate metrics, not ground-truth arc sequences.')
P('Start the API with: <b>uvicorn pathsnap.api.main:app --host 0.0.0.0 --port 8000</b>. Serve the UI with <b>python -m http.server 8080 --directory pathsnap/ui</b> and open the UI with ?api=http://&lt;Laptop-1-LAN-IP&gt;:8000. Both devices must be on the same network and Laptop 1 must allow inbound TCP port 8000.')
P('8. Limitations, integrity and next steps','Heading1');P('The supplied archive does not include evaluator-testing data. The current API defaults to the student_test partition only for development demonstration; do not use these ten trips as the final evaluator partition. When organiser evaluator data is supplied, put it in Student folder/evaluator_test and set PATHSNAP_TRIP_PARTITION=evaluator_test before starting the API. The UI must not receive route labels. The route-constrained nearest-segment target is an approximation and may not represent independently verified physical ground truth. GPS gaps, multiple network components, local metric approximation, and the fixed HMM transition penalty remain limitations. All results in this report are reproducible from the included scripts and are not fabricated.')
P('The team should run the scripts in order, inspect the CSVs and plots, verify the API on every permitted trip, and be prepared to explain the candidate labels, class imbalance, metrics, Bayesian search, transition model and observed HMM accuracy/continuity trade-off. This report is a generated technical draft; team members should review and edit it to reflect their own understanding before submission.')
P('Appendix: generated artifacts','Heading1');P('Dataset inventory: pathsnap/results/dataset_inventory.csv. Network connectivity: pathsnap/results/network_connectivity.csv. Model comparison: pathsnap/results/model_comparison.csv. Bayesian trials: pathsnap/results/bayesian_trials.csv. Decoder comparison: pathsnap/results/route_decoder_comparison.csv. Tuned student metrics: pathsnap/results/tuned_model_student_metrics.json. Folium map: pathsnap/visuals/trip_00000000_eda.html.')
SimpleDocTemplate(str(OUT/'PathSnap_Technical_Report.pdf'),pagesize=A4,rightMargin=1.6*cm,leftMargin=1.6*cm,topMargin=1.6*cm,bottomMargin=1.6*cm,title='PathSnap Technical Report').build(story)
print(OUT/'PathSnap_Technical_Report.pdf')
